INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Fehleranalyse ein wichtiger Teil der Netzwerkverwaltung?', 2, '[{"text": "Ja", "correct": true, "because": "Sie hilft, Probleme zu identifizieren und zu beheben"}, {"text": "Nein", "correct": false, "because": "Fehleranalyse ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Fehleranalyse ohne spezielle Tools durchgeführt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Manuelle Methoden sind möglich, aber ineffizient"}, {"text": "Nein", "correct": false, "because": "Tools erleichtern die Analyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird ICMP häufig bei der Fehleranalyse verwendet?', 2, '[{"text": "Ja", "correct": true, "because": "ICMP (z. B. ping) testet Erreichbarkeit"}, {"text": "Nein", "correct": false, "because": "ICMP ist ein Standardwerkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Fehlerprotokolle bei der Analyse immer dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Dokumentation hilft bei Nachverfolgung"}, {"text": "Nein", "correct": false, "because": "Dokumentation ist Best Practice"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Fehleranalyse auch die Netzwerksicherheit überprüfen?', 2, '[{"text": "Ja", "correct": true, "because": "Sicherheitsprobleme können Fehler verursachen"}, {"text": "Nein", "correct": false, "because": "Sicherheit ist oft Teil der Analyse"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird häufig verwendet, um die Erreichbarkeit eines Geräts bei der Fehleranalyse zu prüfen?', 2, '[{"text": "Ping", "correct": true, "because": "Ping nutzt ICMP zur Erreichbarkeitsprüfung"}, {"text": "Wireshark", "correct": false, "because": "Wireshark analysiert Pakete"}, {"text": "Notepad", "correct": false, "because": "Kein Analysewerkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll hilft, den Pfad von Paketen im Netzwerk zu analysieren?', 3, '[{"text": "ICMP", "correct": true, "because": "ICMP wird von Traceroute genutzt"}, {"text": "HTTP", "correct": false, "because": "Für Webzugriff, nicht Analyse"}, {"text": "DHCP", "correct": false, "because": "Für IP-Vergabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool ist spezialisiert auf die detaillierte Analyse von Netzwerkpaketen?', 2, '[{"text": "Wireshark", "correct": true, "because": "Wireshark zeigt Paketdetails"}, {"text": "Ping", "correct": false, "because": "Nur Erreichbarkeit"}, {"text": "Netstat", "correct": false, "because": "Zeigt Verbindungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein häufiger erster Schritt bei der Fehleranalyse im Netzwerk?', 2, '[{"text": "Prüfung der Erreichbarkeit", "correct": true, "because": "Testet grundlegende Konnektivität"}, {"text": "Neustart des Servers", "correct": false, "because": "Nicht immer nötig"}, {"text": "Änderung der IP-Adresse", "correct": false, "because": "Zu spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Metrik wird oft untersucht, um Verzögerungen im Netzwerk zu erkennen?', 2, '[{"text": "Latenz", "correct": true, "because": "Latenz misst Verzögerungen"}, {"text": "Bandbreite", "correct": false, "because": "Misst Kapazität"}, {"text": "Prozessorlast", "correct": false, "because": "Gerätespezifisch"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Tools werden typischerweise für die Fehleranalyse im Netzwerk verwendet?', 4, '[{"text": "Ping", "correct": true, "because": "Prüft Erreichbarkeit"}, {"text": "Traceroute", "correct": true, "because": "Zeigt Paketpfad"}, {"text": "Wireshark", "correct": true, "because": "Analysiert Pakete"}, {"text": "Texteditor", "correct": false, "because": "Kein Analysewerkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle sind bei der Fehleranalyse hilfreich?', 3, '[{"text": "ICMP", "correct": true, "because": "Für ping und Traceroute"}, {"text": "SNMP", "correct": true, "because": "Für Statusüberwachung"}, {"text": "TCP", "correct": true, "because": "Für Verbindungsanalyse"}, {"text": "FTP", "correct": false, "because": "Für Dateitransfer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fehler können durch Netzwerkanalyse erkannt werden?', 4, '[{"text": "Verbindungsabbrüche", "correct": true, "because": "Zeigt Erreichbarkeitsprobleme"}, {"text": "Hohe Latenz", "correct": true, "because": "Verzögerungen sichtbar"}, {"text": "Paketverlust", "correct": true, "because": "Datenverlust erkennbar"}, {"text": "Bildschirmflimmern", "correct": false, "because": "Hardwareproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Fehleranalyse?', 3, '[{"text": "Problemidentifikation", "correct": true, "because": "Erster Schritt"}, {"text": "Test der Erreichbarkeit", "correct": true, "because": "Grundlegende Diagnose"}, {"text": "Dokumentation", "correct": true, "because": "Für Nachverfolgung"}, {"text": "Softwareinstallation", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Metriken sind bei der Fehleranalyse wichtig?', 3, '[{"text": "Latenz", "correct": true, "because": "Zeigt Verzögerungen"}, {"text": "Paketverlust", "correct": true, "because": "Zeigt Datenverlust"}, {"text": "Bandbreitennutzung", "correct": true, "because": "Zeigt Auslastung"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Irrelevant"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ping ist ein Tool für die Fehleranalyse. b) Fehleranalyse ist nur für Sicherheitsprobleme relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ping ja, Analyse auch für Leistung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ICMP wird für Traceroute genutzt. b) Wireshark ist nur für Erreichbarkeitstests geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ICMP ja, Wireshark für Paketanalyse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlerprotokolle sollten dokumentiert werden. b) Latenz ist irrelevant für die Fehleranalyse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation ja, Latenz wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Traceroute zeigt den Paketpfad im Netzwerk. b) Fehleranalyse kann ohne Tools effizient sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Traceroute ja, Tools nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Paketverlust kann mit Wireshark erkannt werden. b) Fehleranalyse ist ein einmaliger Prozess.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wireshark ja, Analyse fortlaufend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

